using System;using System.Text;using LWS.TruckSports;using LWS.TruckTeaParty;using LWS.TruckFareFight;using LWS.TruckBowling;using LWS.TruckFieldGoal;using UnityEngine;using UnityEngine.InputSystem;
namespace LWS.TruckDentist {
 public sealed class DentistMatch:SportsEventSession {
  public ServingArm[] arms;public DentalTool[] tools;public DentalTooth[] teeth;public DentalPatient patient;public FieldGoalCrowd crowd;public SportsDrivingViews drivingViews;public SportsEventCamera broadcast;public DentalRules rules=new DentalRules();public Key[] workKeys={Key.Q,Key.PageUp,Key.Y,Key.O},cycleKeys={Key.E,Key.PageDown,Key.B,Key.P};public readonly int[] ToolContactCounts=new int[6];public int CorrectExtractions{get;private set;}public int NativeToolContacts{get;private set;}public int NativeExtractions{get;private set;}public int CorrectSteps{get;private set;}public float MaximumObservedForce{get;private set;}
  readonly RaycastHit[] aiTipHits=new RaycastHit[32];
  readonly int[] aiRouteTooth={-1,-1,-1,-1},aiRoutePhase=new int[4];readonly Vector3[] aiRetreat=new Vector3[4];
  readonly FareFightRoute[] routes=new FareFightRoute[4];readonly bool[] extrasReleased=new bool[4],cycled=new bool[4];readonly int[] targets=new int[4];readonly StringBuilder standings=new StringBuilder(300);int preparedRound=-1;
  public override string Title=>"TRUCK DENTIST";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override int WeatherCount=>1;public override bool SupportsSplitAIViews=>true;public override bool CompactBroadcastStatus=>true;public override bool CompactViewportHud=>true;public override int CompactScoreColumns=>4;public override bool MultiViewHUD=>drivingViews!=null&&!drivingViews.NeedsArena;public override string OptionLabel=>option==0?"THREE PATIENT CHECKUPS":option==1?"FIVE PATIENT CHECKUPS":"SEVEN PATIENT CHECKUPS";public override string Header=>Title+" · CHECKUP "+(rules.Round+1)+" / "+rules.Rounds;public override string Status=>rules.ReadySeconds>0?"READY · "+Mathf.CeilToInt(rules.ReadySeconds):rules.Complete?"":Mathf.CeilToInt(rules.RoundSeconds)+"s · PRECISE TOOL CONTACT";
  public override string Help=>"Inside a giant cartoon mouth, use your original NWH truck and physical articulated arm to treat three marked teeth and protect the healthy one. Original profiles, drive, pause, shared/chase/cab, free look and rematch remain. Hold ACTION plus drive/steer to adjust wrist height/yaw while the original NWH handbrake holds. TOOL: Q/PageUp/Y/O, whole RB, own half shoulder. NEXT TOOL: E/PageDown/B/P, whole West, own half stick-click; cycles toothbrush, drill, extraction forceps, air, water and cleaner/filling polisher. A fresh ACTION also releases an extracted clamped tooth. Every procedure requires actual selected tool contact with the correct tooth; position, real tip movement and native force matter. Dirty tooth: WATER, BRUSH, CLEANER, AIR. Cavity: WATER, DRILL, WATER, CLEANER to fill, AIR to dry. Loose marked tooth: WATER then clamp with EXTRACTION held, lift the arm and pull until the actual socket joint releases. No automatic extraction by a timer. Keep other tools away from healthy teeth. Rushing above2.8m/s or excessive native force loses points and can break a tooth; dangerous wrong tools lose points. Rinsing and drying do not damage healthy teeth; the solid wrist tray or truck can still dislodge them. Retract before moving sideways and use the central aisle to change rows. Correct treatment stages score once; actual correct extraction scores90. Each checkup allows180seconds; three/five/seven form the match. AI selects and physically applies the same tools/arm/contacts. Patient reactions are playful and non-graphic; no blood. Rematch restores the original finite tooth/socket state and scores.";
  public static float X(int s)=>(s-1.5f)*34;
  public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;for(int i=0;i<setup.count;i++){if(setup.players[i].source!=BowlingSource.Keyboard)continue;foreach(var k in new[]{workKeys[i],cycleKeys[i]}){if(k==Key.None||k==Key.Escape||workKeys[i]==cycleKeys[i]){reason="Choose distinct dentist tool/cycle keys; Escape remains pause.";return false;}for(int j=0;j<setup.count;j++){var p=setup.players[j];if(p.source==BowlingSource.Keyboard&&(k==p.forward||k==p.back||k==p.left||k==p.right||k==actionKeys[j]||j!=i&&(k==workKeys[j]||k==cycleKeys[j]))){reason="Dentist binding conflicts with driver "+(j+1);return false;}}}}return true;}
  public override bool TryReadScoreCard(int slot,out string score,out string detail){bool valid=slot>=0&&slot<setup.count;score=valid?rules.points[slot]+" PTS":"";detail=valid?rules.procedures[slot]+" TREATED · "+rules.mistakes[slot]+" MISTAKES":"";return valid;}public override bool TryReadViewportCard(int view,out int participant,out string score,out string detail)=>TryReadDrivingViewportCard(drivingViews,view,out participant,out score,out detail);public override string ViewportTelemetry(int view)=>Readout(drivingViews.rally.owners[view]);public override string ViewText(int view){int s=drivingViews.rally.owners[view];return setup.players[s].name+" · "+rules.points[s]+" PTS\n"+Readout(s);}public string Readout(int s){int id=targets[s],expected=rules.Expected(id);return tools[s].Kind.ToString().ToUpperInvariant()+" · "+(expected>=0?DentalRules.Task(id)+" / "+((DentalToolKind)expected).ToString().ToUpperInvariant():"CHECKUP COMPLETE")+" · "+rules.work[id].ToString("F1")+"s";}
  public override string Standings{get{standings.Clear();for(int p=1;p<=setup.count;p++)for(int s=0;s<setup.count;s++)if(rules.Place(s)==p)standings.Append('#').Append(p).Append(' ').Append(setup.players[s].name).Append(" · ").Append(rules.points[s]).Append(" PTS · ").Append(rules.procedures[s]).Append(" TEETH · ").Append(rules.mistakes[s]).Append(" MISTAKES\n");return standings.ToString();}}public override string Results=>"CARTOON CLINIC CHECKUPS COMPLETE\n\n"+Standings;
  protected override void BeginGame(){if(arms.Length!=4||tools.Length!=4||teeth.Length!=16||patient==null||drivingViews==null)throw new InvalidOperationException("Author all four complete physical dentist workspaces.");rules.Reset(setup.count,option==0?3:option==1?5:7);NativeToolContacts=NativeExtractions=CorrectSteps=0;MaximumObservedForce=0;CorrectExtractions=0;Array.Clear(ToolContactCounts,0,6);preparedRound=-1;PrepareRound();drivingViews.Layout();patient.Prepare();crowd?.ResetAttempt();}
  void PrepareRound(){preparedRound=rules.Round;foreach(var t in tools)t.Release();for(int i=0;i<4;i++){arms[i].gameObject.SetActive(i<setup.count);targets[i]=i*4;aiRouteTooth[i]=-1;aiRoutePhase[i]=0;extrasReleased[i]=cycled[i]=false;routes[i]??=new FareFightRoute();routes[i].Reset();if(i<setup.count)arms[i].Prepare(new Vector3(X(i),.65f,-18),Quaternion.identity);tools[i].Prepare();}foreach(var tooth in teeth){tooth.gameObject.SetActive(tooth.id/4<setup.count);if(tooth.id/4<setup.count)tooth.Prepare();}Physics.SyncTransforms();}
  static void Hold(SportsEventTruck t){t.TickDrive(Vector2.zero);t.tractorMotor.vehicle.input.states.handbrake=t.tractorMotor.vehicle.input.states.handbrakeRaw=1;}
  protected override void Simulate(float dt){rules.Tick(dt);if(rules.Complete){for(int s=0;s<setup.count;s++)if(rules.Place(s)==1)ConfirmOutcome("dentist-champion:"+s,s,rules.points[s],"GENTLE DENTIST","PTS",SportsScoreTier.MatchChampion,matchEnded:true);EndMatch();return;}if(preparedRound!=rules.Round)PrepareRound();if(!rules.Active){for(int i=0;i<setup.count;i++)Hold(arms[i].truck);return;}for(int i=0;i<setup.count;i++){var arm=arms[i];arm.clock=rules.Clock;tools[i].Running=false;if(setup.players[i].source==BowlingSource.AI)Bot(i,dt);else{bool work=Extra(i,true),cycle=Extra(i,false);if(cycle&&!cycled[i])tools[i].Select((DentalToolKind)(((int)tools[i].Kind+1)%6));cycled[i]=cycle;bool adjust=ActionHeld(i);if(actions[i])tools[i].Release();if(adjust)Hold(arm.truck);else arm.truck.TickDrive(commands[i]);arm.Manual(commands[i],adjust,false,dt);tools[i].Running=work;}tools[i].Tick(dt);}foreach(var t in teeth)if(t.gameObject.activeInHierarchy)t.Tick();}
  bool Extra(int slot,bool work){var p=setup.players[slot];if(!Ready(slot)||!p.released){extrasReleased[slot]=false;return false;}bool raw(bool w){if(p.source==BowlingSource.Keyboard)return SportsDeviceInput.KeyHeld(w?workKeys[slot]:cycleKeys[slot]);if(!p.Controller)return false;if(p.source==BowlingSource.WholeController)return w?p.pad.rightShoulder.isPressed:p.pad.buttonWest.isPressed;bool right=p.source==BowlingSource.RightStick;return w?(right?p.pad.rightShoulder:p.pad.leftShoulder).isPressed:(right?p.pad.rightStickButton:p.pad.leftStickButton).isPressed;}if(!extrasReleased[slot]){if(raw(true)||raw(false))return false;extrasReleased[slot]=true;}return raw(work);}
  bool Approach(int s,Vector3 goal,float dt){var truck=arms[s].truck;var delta=Vector3.ProjectOnPlane(goal-truck.body.position,Vector3.up);if(delta.magnitude<1){Hold(truck);return truck.body.linearVelocity.magnitude<.5f;}float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up),delta,Vector3.up);if(Mathf.Abs(angle)>110&&Mathf.Abs(Vector3.Dot(delta,truck.transform.right))<6){float reverse=Vector3.SignedAngle(Vector3.ProjectOnPlane(-truck.transform.forward,Vector3.up),delta,Vector3.up);truck.TickDrive(new Vector2(-Mathf.Clamp(reverse/42,-1,1),-.4f));return false;}routes[s].DirectGoal(truck.body.position,goal);var drive=routes[s].Drive(truck.body,truck.transform,(int)setup.players[s].difficulty,dt,1);drive.y=Mathf.Clamp(drive.y,-.4f,.5f);truck.TickDrive(drive);return false;}
  // Real wrist waypoints keep the solid tray in front of each tooth row
  // before lateral movement. Retract/centre before driving; drive with the
  // original wrist retracted in the central aisle, then park/align/approach.
  // The original NWH truck and ServingArm.Move remain the only pose writers.
  bool GuideTooth(int s,int id,float dt){var arm=arms[s];var tool=tools[s];var tooth=teeth[id];if(aiRouteTooth[s]!=id){int old=aiRouteTooth[s];float beforeRow=teeth[old>=0?old:id].spawn.z-5;aiRetreat[s]=new Vector3(arm.grip.position.x,arm.grip.position.y,Mathf.Min(arm.grip.position.z,beforeRow));aiRouteTooth[s]=id;aiRoutePhase[s]=0;}Vector3 goal;
   if(aiRoutePhase[s]==0){Hold(arm.truck);goal=aiRetreat[s];arm.Move(goal,0,false,dt);if(Vector3.Distance(arm.grip.position,goal)<.06f)aiRoutePhase[s]=1;return false;}
   if(aiRoutePhase[s]==1){Hold(arm.truck);goal=new Vector3(X(s),aiRetreat[s].y,aiRetreat[s].z);arm.Move(goal,0,false,dt);if(Vector3.Distance(arm.grip.position,goal)<.06f)aiRoutePhase[s]=2;return false;}
   if(aiRoutePhase[s]==2){bool parked=Approach(s,new Vector3(X(s),0,id%4<2?0:10),dt);goal=arm.truck.transform.TransformPoint(new Vector3(0,2.5f,3));arm.Move(goal,0,false,dt);if(parked&&Vector3.Distance(arm.grip.position,goal)<.06f)aiRoutePhase[s]=3;return false;}
   Hold(arm.truck);Vector3 treatment=GentleTipTarget(tooth,tool),gripGoal=treatment-tool.PhysicalTipOffset;
   if(aiRoutePhase[s]==3){goal=new Vector3(gripGoal.x,gripGoal.y,tooth.spawn.z-5);arm.Move(goal,0,false,dt);if(Vector3.Distance(arm.grip.position,goal)<.06f)aiRoutePhase[s]=4;return false;}
   float remaining=Vector3.Distance(tool.PhysicalTip,treatment);float precisionSpeed=Mathf.Clamp(remaining,.05f,1);Vector3 command=remaining<.8f?Vector3.MoveTowards(arm.grip.position,gripGoal,dt*precisionSpeed):gripGoal;arm.Move(command,0,false,dt);return remaining<.55f;
  }
  Vector3 GentleTipTarget(DentalTooth tooth,DentalTool tool){Vector3 forward=Vector3.ProjectOnPlane(tool.arm.truck.transform.forward,Vector3.up).normalized;var sphere=tool.tips[(int)tool.Kind];Vector3 scale=sphere.transform.lossyScale;float radius=sphere.radius*Mathf.Max(Mathf.Abs(scale.x),Mathf.Abs(scale.y),Mathf.Abs(scale.z));Vector3 origin=tooth.body.position+Vector3.up*1.6f-forward*4;int count=Physics.SphereCastNonAlloc(origin,radius,forward,aiTipHits,8,~0,QueryTriggerInteraction.Ignore);var hits=aiTipHits;if(count==hits.Length){hits=Physics.SphereCastAll(origin,radius,forward,8,~0,QueryTriggerInteraction.Ignore);count=hits.Length;}float nearest=float.PositiveInfinity;for(int i=0;i<count;i++){var c=hits[i].collider;if(c!=null&&c.enabled&&!c.isTrigger&&c.attachedRigidbody==tooth.body&&hits[i].distance<nearest)nearest=hits[i].distance;}if(!float.IsFinite(nearest))throw new InvalidOperationException("Actual solid tooth compound surface required for dental approach.");return origin+forward*(nearest+(sphere.isTrigger?.002f:0f));}
  void Bot(int s,float dt){int id=s*4;while(id<s*4+3&&rules.done[id])id++;targets[s]=id;var arm=arms[s];var tool=tools[s];if(id>=s*4+3){Hold(arm.truck);return;}var tooth=teeth[id];int expected=rules.Expected(id);if(expected<0)return;if(tool.Gripped==tooth){Hold(arm.truck);tool.Running=true;arm.Move(tooth.spawn+Vector3.up*5-tool.PhysicalTipOffset,0,false,dt);return;}
   // Never activate a new solid tool while its sphere already overlaps enamel.
   // Withdraw physically to the same proven row-front lane before selecting.
   if(aiRouteTooth[s]==id&&aiRoutePhase[s]==4&&(int)tool.Kind!=expected){Hold(arm.truck);Vector3 retreat=new Vector3(arm.grip.position.x,arm.grip.position.y,tooth.spawn.z-5);arm.Move(retreat,0,false,dt);if(Vector3.Distance(arm.grip.position,retreat)<.06f)tool.Select((DentalToolKind)expected);return;}
   bool ready=GuideTooth(s,id,dt);if(aiRoutePhase[s]==4&&(int)tool.Kind!=expected){tool.Select((DentalToolKind)expected);return;}tool.Running=ready&&(int)tool.Kind==expected;
  }
  public void NativeWork(DentalTooth tooth,DentalTool tool,float speed,float force){if(!Live||!rules.Active)return;NativeToolContacts++;ToolContactCounts[(int)tool.Kind]++;MaximumObservedForce=Mathf.Max(MaximumObservedForce,force);int delta=rules.Contact(rules.Round,tooth.id,tool.arm.truck.slot,tool.Kind,Time.fixedDeltaTime,speed,force);if(delta!=0){if(delta<0)tooth.Mistreatment();else CorrectSteps++;ConfirmScore("dental:"+rules.Round+":"+tooth.id+":"+rules.stage[tooth.id]+":"+rules.mistakes[tool.arm.truck.slot],tool.arm.truck.slot,delta,rules.points[tool.arm.truck.slot],delta>0?"PRECISE DENTAL CARE":"TOO ROUGH / WRONG TOOL",delta>=30?SportsScoreTier.Major:SportsScoreTier.Small);patient.React(delta>0);feedback.PlayAt(delta>0?3:4,tooth.body.position,speed);}}
  public void NativeExtraction(DentalTooth tooth,DentalTool tool){bool actualGrip=tool.Kind==DentalToolKind.Extractor&&tool.Gripped==tooth;int slot=tool.arm.truck.slot;int delta=rules.SocketBroke(rules.Round,tooth.id,slot,actualGrip);if(delta==0)return;NativeExtractions++;if(delta>0)CorrectExtractions++;ConfirmScore("socket:"+rules.Round+":"+tooth.id,slot,delta,rules.points[slot],delta>0?"CORRECT TOOTH EXTRACTED":"WRONG TOOTH DISLODGED",delta>0?SportsScoreTier.Major:SportsScoreTier.Small);patient.React(delta>0);feedback.PlayAt(delta>0?5:4,tooth.body.position,0,true);}
  public override void DescribeBroadcast(SportsBroadcastAction action,SportsBroadcastFraming source){int s=source.Nearest(Vector3.zero,true);if(s<0)s=0;action.primary=s;action.Objective(teeth[Mathf.Clamp(targets[s],0,teeth.Length-1)].body.position,2.4f);action.reason="ACTUAL TOOL / TREATMENT TARGET / PATIENT REACTION";}
  protected override void Present(float dt){if(!Running)return;patient.Tick(dt);drivingViews.Tick(dt);if(drivingViews.NeedsArena&&broadcast.LegacyPoseAllowed)broadcast.Pose(arms[0].truck.body.position,new Vector3(0,21,-30),60);}public override void ExtraAction(string key){if(key=="drivingview")drivingViews.Cycle();}protected override void StopSounds(){if(arms!=null)foreach(var a in arms)if(a!=null)a.truck.StopSound();if(tools!=null)foreach(var t in tools)if(t!=null&&t.workAudio!=null)t.workAudio.Stop();}protected override void StopGame(){if(tools!=null)foreach(var t in tools)if(t!=null){t.Running=false;t.Release();}if(arms!=null)foreach(var a in arms)if(a!=null)a.Freeze();if(teeth!=null)foreach(var t in teeth)if(t!=null)t.Freeze();StopSounds();}
 }
